pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 2.0 * diff; // penalize mismatch
        if post_residual == next_item_size {
            score -= 50.0; // perfect 2-step fit bonus
        } else if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score -= 15.0; // near-perfect chainable fit
        }
    } else {
        // Last item: just minimize waste, slight bonus for tight fit.
        score -= 5.0;
    }

    // Relative-to-mean coupling: prefer bins whose post residual stays near mean residual
    // (keeps bin pool homogeneous and reusable), unless exact lookahead match overrides.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize leaving tiny unusable slivers (dead space) unless next item matches.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the new bin enables a perfect 2-step chain
    // (post_residual in fresh bin == next_item_size), otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0; // fresh bin with perfect chain
        } else if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
            score -= 20.0; // fresh bin with near chain
        } else {
            score += 25.0 + 0.5 * open_bins_count as f64; // discourage wasting a fresh bin
        }
    }

    // Early stream: slightly more willing to open bins (build diversity of residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

