pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items of size 10..80 mean residuals
    // that are multiples of small harmonics are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fit: residual exactly zero -> heavily reward.
    if pr == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual divisible by 10/20/25/50 is "usable"
    // by future items drawn from integer sizes; reward divisibility.
    if pr % 10 == 0 && pr > 0 { score -= 12.0; }
    if pr % 20 == 0 && pr > 0 { score -= 6.0; }
    if pr % 25 == 0 && pr > 0 { score -= 6.0; }
    if pr % 50 == 0 && pr > 0 { score -= 8.0; }

    // Small dead space (unusable for typical items) -> penalize.
    if pr > 0 && pr < 10 { score += 60.0; }
    // Medium awkward zone (10..20): mildly penalize unless harmonic.
    else if pr > 0 && pr < 20 { score += 15.0; }

    // Fraction-of-capacity thresholds on post_residual.
    let frac = prf / cap;
    if frac > 0.5 { score -= 10.0; }       // bin still half empty, keep it flexible
    else if frac > 0.25 { score -= 3.0; }  // moderately usable
    else if pr > 0 { score += 8.0; }       // small leftover, less useful

    // Lookahead coupling: if next item fits the post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= pr {
            score -= 40.0 + 0.3 * nx as f64;
            // exact harmonic match: next item exactly fills remainder
            if nx == pr { score -= 120.0; }
            // next item leaves a harmonic remainder too
            let nxt_res = pr - nx;
            if nxt_res % 10 == 0 { score -= 10.0; }
        } else {
            // next item won't fit here; penalize wasting large residuals
            score += 5.0 + 0.1 * (nx - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits (post_residual already does)
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // if existing bins are fragmented (high mean residual spread vs item),
        // opening fresh is less bad
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // large items keep new bins attractive (hard to fit later)
        if item_size > 60 { score -= 15.0; }
    }

    // Mild pressure to fill nearly-full bins when many bins are open.
    if open_bins_count > 4 && prf < 0.3 * cap && pr > 0 {
        score -= 6.0;
    }

    score
}

