    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that still leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // leftover too small for next item: dead space
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize spreading across many bins.
    score += 4.0 * open_bins_count as f64;

    // Mean residual coupling: bins deviating far below the mean are wasteful targets.
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Late-stream tightening: preserve flexibility early, pack tightly later.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 80.0; // perfect 2-step chain
        }
        // Penalize leaving residual the next item cannot use.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 50.0;
    }

    // Relative-to-mean residual shaping: avoid bins with unusually large residuals
    // unless they would otherwise be wasted.
    if bin_residual != bin_capacity {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But opening a new bin is attractive when the next item pairs with the
        // current one to nearly fill it (two-item combo).
        if next_item_size > 0 {
            let combo_gap = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs();
            score -= (2.0 * combo_gap.max(0) as f64).min(65.0);
        }
        // Prefer opening new bins late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), with a soft non-linear horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = (progress * std::f64::consts::PI).sin(); // 0 -> 1 -> 0

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste * waste * bin_capacity as f64;

    // Perfect fit bonus (subtract heavily).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into the post-residual,
    // this placement is highly desirable (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space that the lookahead cannot use: penalize proportionally.
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // If next item is large and this bin would be nearly empty anyway,
        // slightly favor conserving fuller bins for small leftovers.
        if next_item_size >= 70 && post_residual > 0 && post_residual < 20 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer the fullest bin that fits (best-fit style),
        // i.e. penalize bins with lots of residual relative to the mean.
        let rel = bin_residual as f64 - mean_residual;
        score += 0.5 * rel;
    }

    // Global state coupling: many open bins -> encourage consolidation
    // (favor filling existing bins over opening new ones).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * waste;

    // New-bin candidate handling: an empty bin gets a baseline cost that
    // shrinks late in the stream or when existing bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let new_bin_cost = 55.0
            - 25.0 * fragmentation
            - 20.0 * horizon * fragmentation
            - (if fitting_bins_count == 0 { 40.0 } else { 0.0 });
        score = new_bin_cost + waste * bin_capacity as f64;
        // If lookahead is huge and no open bin could take it next either,
        // opening fresh is more attractive.
        if next_item_size > 0 && next_item_size >= 60 && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild time-horizon modulation: early on, be a bit greedy about tight fits;
    // late in the stream, tolerate leftovers less (dead space is permanent).
    score += 4.0 * horizon * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: wasted space, softly normalized with non-linear penalty on tiny residuals
    let mut score = fit_frac * (1.0 + 2.0 * (1.0 - fit_frac) * (1.0 - fit_frac));

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, larger leftovers are increasingly penalized (quartic ramp)
    let prog_coupling = (pr / cap).powi(2) * (progress * progress * (3.0 - 2.0 * progress)) * 6.0;
    score += prog_coupling;

    // Perfect-fit reward (smooth bump near zero residual)
    score -= 3.0 * (-(fit_frac * cap / 6.0).powi(2)).exp();

    // Lookahead: penalize if next item won't fit in the leftover
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 1.5 * ((nx - pr) / cap) * (0.5 + progress);
        } else {
            score -= 0.8 * (1.0 - (nx / pr)) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * ((open_bins_count as f64 / 10.0).tanh()) * fit_frac;

    // Mean-residual deviation coupling: bins far from mean residual get slight penalty
    score += 0.2 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;           // 25
    let eighth = bin_capacity / 8;            // 12
    let post = post_residual;

    // Penalize post_residuals that fall in "dead zones": too small to fit
    // typical future items but large enough to waste capacity.
    if post > 0 && post < eighth {
        score += 30.0;                        // nearly useless sliver
    } else if post >= eighth && post < quarter {
        score += 12.0;                        // awkward quarter band
    } else if post == 0 {
        score -= 25.0;                        // perfect closure
    } else if post >= quarter && post < bin_capacity / 2 {
        score -= 6.0;                         // decent usable band
    }

    // Modulo-10 class of post_residual: prefer residuals that are round
    // (likely to match future integer item sizes exactly).
    let m = post % 10;
    score -= match m {
        0 => 8.0,
        1 | 9 => 2.0,
        5 => 3.0,
        _ => 0.0,
    };

    // Exact lookahead fit: if the next item exactly consumes the post_residual,
    // strongly reward this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == post {
        score -= 40.0;
    } else if next_item_size > 0 && post > 0 && next_item_size <= post {
        // Next item fits: reward proportionally to how much it consumes.
        let fill_next = next_item_size as f64 / post as f64;
        score -= 15.0 * fill_next;
    } else if next_item_size > post && post > 0 {
        // Next item won't fit here: slight penalty proportional to stranded space.
        score += (post as f64) * 0.05;
    }

    // Integer-division threshold: how many "eighth slots" remain after placement?
    let eighths_left = post / eighth.max(1);
    score -= eighths_left as f64 * 2.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity or no bin fits well.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 20.0;                    // forced open
        } else if frac > 0.5 {
            score += 10.0;                    // prefer reusing a bin for big items
        } else {
            score += 18.0;                    // keep small items in existing bins
        }
    }

    // Stream progression: early on, be pickier about residual quality;
    // late in the stream, favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post as f64) * 0.10;

    // Coupling with mean residual: if this bin's post-residual is far below
    // the mean, it's a tight fit — reward it.
    score -= (mean_residual - post as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (min size 1..=10) can use it well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0; // tiny unusable slivers
    } else if post_residual == 0 {
        score -= 45.0; // perfect fit: strongly rewarded
    } else if post_residual <= 20 {
        score += 12.0; // semi-dead zone: awkward gap
    }

    // Reward tight fits proportionally (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: if this is the ONLY bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 35.0 + open_bins_count as f64 * 6.0;
        // Early in stream, opening bins is cheaper (need spread of residuals).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If no existing bin fits well, new bin is more attractive.
        if post_residual == bin_capacity - item_size && item_size > 50 {
            score -= 15.0;
        }
    } else {
        // Slight reward for using existing bins as open count grows.
        score -= open_bins_count as f64 * 1.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already a "junk" bin; using it cleans up the bin set.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 4.0 * dev.sqrt();
    } else {
        score += 2.0 * (-dev).sqrt();
    }

    // Lookahead: if the next item fits exactly into the post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0; // next item can still use the gap
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 20.0; // gap is dead even for the lookahead item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item would leave a small residual afterwards.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step_left = post_residual - next_item_size;
        if two_step_left <= 10 {
            score -= 400.0 - 30.0 * two_step_left as f64;
        } else {
            score -= 60.0 / (two_step_left as f64).sqrt();
        }
    }

    // Penalize post_residual too small for the next item (dead space risk),
    // especially when residual is tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Tight fit reward: item nearly fills the bin.
    if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate: penalize leaving loose space, favor new bins less.
    score += progress * (post_residual as f64 * 0.3);

    // New empty bin candidate: baseline cost so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild penalty for many open bins to discourage spreading.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item could exactly fill the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item would fit in post-residual, mild reward for keeping usable space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally.
        score += 4.0 + 0.05 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 15.0 * pressure + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Global state: prefer filling bins when many are open (consolidation pressure).
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be pickier (penalize loose fits) to preserve options.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (1.0 - fit_ratio);

    // Prefer bins with residual above the current mean (keep balanced spread).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer small post-residual, with non-linear emphasis
    let mut score = norm_pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, dead space becomes more costly (non-linearly)
    let progress_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 1.5 * progress_term * norm_pr * norm_pr;

    // Reward tight fits (post_residual near zero) more strongly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 1.5 * progress);

    // Penalize bins whose residual deviates from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.4 * dev * dev;

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.0 * progress;
    }

    // Lookahead: if next item fits exactly into post-residual, reward heavily
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 1.2 * (1.0 - gap * gap);
    } else if next_item_size > 0 {
        // next item won't fit: mildly penalize leaving awkward residual
        score += 0.3 * norm_pr * (1.0 - progress);
    }

    // New-bin candidate: make empty bin moderately attractive only when
    // current item leaves very little room for the next item elsewhere
    if bin_residual == bin_capacity {
        let next_big = next_item_size as f64 / cap;
        score = 0.8 + 0.5 * next_big - 0.3 * progress;
    }

    // Mild penalty for proliferating open bins early
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes.
    // Class 0: post_residual >= 80 (huge leftover, great bin)
    // Class 1: 50..=79 (medium)
    // Class 2: 20..=49 (small-ish)
    // Class 3: 1..=19 (near-dead space)
    let dead_threshold = 19u32;
    if post_residual == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if post_residual <= dead_threshold {
        // Dead space: can likely never be reused (min item ~10, distribution unknown up to 100)
        // Penalize proportionally, but a tiny leftover is better than wasting a whole bin.
        score += (dead_threshold - post_residual + 1) as f64 * 1.5;
        // If this was the ONLY fitting bin, dead space is acceptable rather than opening a bin
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else if post_residual < 50 {
        score += 8.0;
    } else {
        score -= 5.0;
    }

    // Harmonic coupling with next item: reward when next_item_size fits exactly
    // into post_residual (modulo-style match), penalize when it nearly fits (fragmentation).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fit: perfect follow-up
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 19 {
                score -= 15.0; // next item leaves near-perfect state again
            } else {
                score += slack as f64 * 0.1; // mild penalty for loose follow-up
            }
        } else {
            // next item won't fit here; leftover becomes dead weight
            let gap = next_item_size - post_residual;
            if gap <= 19 {
                score += gap as f64 * 0.8; // just missed: bad sign
            } else {
                score += 5.0;
            }
        }
    }

    // Integer-division threshold on residual fraction of capacity
    let frac = post_residual as f64 / cap;
    if frac >= 0.8 {
        score -= 6.0;
    } else if frac <= 0.2 {
        score += 6.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are scarce or fragmented.
        // Base penalty keeps us preferring reuse of open bins.
        score += 30.0;
        // If only one open bin fits, and its fit would be poor (large dead space),
        // opening fresh may win: reduce penalty as mean residual shrinks.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If mean residual across open bins is high, reuse is cheap: penalize new bin more
        score += (mean_residual / cap).max(0.0) * 15.0;
    }

    // Tie-breaker: prefer bins with residual close to item (tight fit) via modulo class
    let tight = (bin_residual - item_size) % 10;
    score -= (10 - tight) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the next item (or next item unknown -> very small gaps).
    let min_useful = if next_item_size > 0 { next_item_size } else { 10 } as f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_useful {
        // Penalize proportionally to how close the gap is to being useless,
        // and to how much space was just consumed (waste of a good bin).
        let deadness = 1.0 - (pr / min_useful);
        score += 60.0 * deadness * deadness;
    }
    // Zero residual is perfect (bin exactly closed).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward exact/near-exact fits scaled by item size (big items filling bins is good).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin candidate and prefer tight fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins are open or stream is late.
        score += 10.0 + 8.0 * pressure + 20.0 * progress;
    } else {
        // Existing bin: mild reward that grows with open-bin pressure.
        score -= 2.0 + 1.5 * pressure;
    }

    // Prefer bins whose residual is below the mean residual (tighter bins first),
    // keeping larger residuals for future larger items.
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.5 * diff;
    }

    // Lookahead coupling: if next item could also fit in the post-residual,
    // reward leaving exactly enough room (chained placement).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let chain_quality = 1.0 - ((pr - ni) / bin_capacity as f64);
            score -= 15.0 * chain_quality.max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let new_bin_score = bin_capacity as f64 - 15.0;
        // If item fits snugly in an open bin, discourage new bin strongly.
        if post_residual <= 10 && fitting_bins_count > 1 {
            return new_bin_score + 40.0;
        }
        // If this is the last-chance bin, opening a new bin is bad.
        if fitting_bins_count == 1 {
            return new_bin_score + 60.0;
        }
        return new_bin_score;
    }

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item: strong reward.
        if diff == 0.0 {
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 25.0 - diff * 3.0;
        } else {
            score += diff * 0.35;
        }
        // Next item must still fit after this placement; penalize if it won't.
        if next_item_size > post_residual {
            score += 12.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.6;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (but allow it when next item matches).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Early in stream: be slightly conservative, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize mildly so we prefer
    // reasonable fits, but keep it competitive against bins that would waste space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0;
        // Late in the stream, opening new bins is cheap; early, consolidate.
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.1;
    }
    // If next item cannot fit here but a tighter bin could chain better, slight penalty
    if next_item_size > 0 && post_residual < next_item_size && post_residual < item_size.min(next_item_size) {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 200.0;
    }

    // Penalize creating tiny unusable dead space (< smallest plausible item chunk)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) relative to mean state.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Global pressure: many open bins with large mean residual -> encourage filling them.
    if !is_new_bin && mean_residual > 40.0 {
        score -= 0.2 * (mean_residual - 40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
