    // smooth polynomial coupling of post_residual with stream progress
    score += norm_pr * norm_pr * (0.5 + progress) * 20.0;
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * progress * 10.0;
    // lookahead: reward leaving space close to next item size (smooth kernel)
    let n = next_item_size as f64;
    if n > 0.0 {
        let diff = (pr - n) / cap;
        score -= (-diff * diff * 40.0).exp() * 8.0;
    }
    // penalize dead space relative to mean residual
    score += (pr - mean_residual).abs() / cap * 5.0;
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }
    // slight preference to fill existing bins rather than open new ones
    score -= open_bins_count as f64 * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are exact multiples of common small item sizes are valuable.
    let pr = post_residual;
    if pr > 0 {
        // Class A: perfectly divisible leftovers (very reusable)
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Class B: leftover fits a typical small item (<= 20)
        if pr <= 20 {
            score -= 4.0;
        } else if pr <= 40 {
            score -= 1.5;
        } else if pr > 70 {
            // huge leftover = wasteful placement of a small item
            score += 3.0;
        }
        // Dead-space penalty: leftover too small for the smallest plausible item
        if pr < 10 {
            score += 12.0;
        }
    } else {
        // Perfect fill: strongly reward closing a bin exactly
        score -= 15.0;
    }

    // Integer-division threshold on next item: does the leftover fit the lookahead?
    if next_item_size > 0 && pr >= next_item_size {
        score -= 5.0;
        // bonus if leftover also leaves room for a third item after the lookahead
        let after_next = pr - next_item_size;
        if after_next >= 10 {
            score -= 2.0;
        }
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        // leftover blocks the lookahead item: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a bin is only sensible when the item
    // is large relative to capacity or existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when open bins have small fragmented residuals
        // and the item is big (hard to place later).
        if item_size as f64 > 0.6 * cap && fragmentation < 0.35 {
            score -= 10.0;
        } else {
            score += 5.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild tie-break: prefer bins tighter than the current mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
