    score += (pr - mean_residual).abs() / cap * 5.0;

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0 + 50.0 * progress;
    }

    // New empty bin candidate: baseline cost so it only wins on poor fits
    if bin_residual == bin_capacity {
        score += 130.0 + 0.5 * mean_residual;
        if n > 0.0 && n <= cap {
            score -= 15.0;
        }
    }

