        }
    }

    // Penalize post_residual too small for the next item (dead space risk),
    // scaled by how close the dead space is to being useful.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        let dead_ratio = gap as f64 / bin_capacity as f64;
        if gap <= 5 {
            score += 60.0 + 4.0 * gap as f64; // near-miss is very costly
        } else {
            score += 25.0 + 0.5 * gap as f64 - 200.0 * dead_ratio;
        }
    }

    // Tight fit reward: item nearly fills the bin.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }
    // Few fitting bins: mild consolidation bonus.
    if fitting_bins_count == 2 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate: penalize leaving loose space, favor new bins less.
    score += progress * (post_residual as f64 * 0.3);

    // New empty bin candidate: baseline cost so it only wins when open bins are poor fits.
    // Stronger barrier early; relax when many bins are open and fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let barrier = 140.0 + 0.5 * mean_residual - 60.0 * scarcity - 30.0 * progress;
        score += barrier;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
        // If no open bin fits at all, opening a new bin is unavoidable — soften fully.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for many open bins to discourage spreading.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
