    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = pr * (1.0 + 0.3 * progress) + 40.0 * poly;

    // Reward tight fits (small post_residual), stronger late in the stream
    score -= (item_size as f64 / cap) * (1.0 + progress) * 15.0;

    // Penalize leaving a gap that cannot fit the lookahead item
    if next_item_size > 0 && pr > 0 && (next_item_size as u32) > post_residual {
        score += 8.0 + 12.0 * progress;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 20.0 * progress;
    }

    // Mild penalty for bins far from mean residual (encourage balanced filling)
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    // New-bin candidate: keep it neutral-slightly high unless current fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Exact 2-step match: leave exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1200.0;
    }

    // Near match: next item fits and leaves only a tiny sliver.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step_left = post_residual - next_item_size;
        if two_step_left <= 12 {
            score -= 450.0 - 30.0 * two_step_left as f64;
        } else {
            score -= 60.0 / (two_step_left as f64).sqrt();
        }
    }

    // Penalize when next item cannot use the remaining space.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        score += 20.0 + 0.6 * gap as f64;
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Tight-fit ladder: reward nearly perfect fills.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 160.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Prefer bins tighter than the running average.
    score -= 0.5 * (mean_residual - pr);

    // Late-stream consolidation pressure on loose space.
    score += progress * (pr * 0.35);

    // Smooth polynomial coupling of post_residual with progress (parent trait, damped).
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (0.5 + progress) * 8.0;

    // New empty bin candidate: pay a cost so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 110.0 + 0.6 * mean_residual + 80.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_cost -= 30.0;
        }
        // Fresh bin can host both current and next item exactly.
        if next_item_size > 0 && post_residual < next_item_size
            && item_size + next_item_size <= bin_capacity {
            new_bin_cost -= 40.0;
        }
        // Few open bins and early stream: opening is cheaper.
        if open_bins_count <= 2 {
            new_bin_cost -= 15.0;
        }
        // MUTATION: penalize opening a new bin harder when several open bins
        // could still fit the item — consolidation pressure.
        if fitting_bins_count >= 2 {
            new_bin_cost += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // MUTATION: opening a new bin wastes the residual slack of open bins;
        // penalize proportionally to the smallest residual we could have used.
        new_bin_cost += 0.15 * mean_residual * (1.0 - progress);
        score += new_bin_cost;
    }

    // Mild penalty for spreading across many bins, stronger late.
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod 10 and integer-division thresholds.
    let pr = post_residual;
    let class = pr % 10;                       // fine harmonic class
    let coarse = pr / 20;                      // coarse band: 0..=5
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward small post_residual nonlinearly (waste grows quadratically).
    score += (pr as f64 * pr as f64) / (2.0 * bin_capacity as f64);

    // Perfect-fit harmonic bonuses: residuals divisible by 5/10 are reusable.
    if pr == 0 {
        score -= 30.0;
    } else if class == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 4.0;
    } else {
        // Odd fragments are dead space; penalize more for small unusable slivers.
        score += (10 - class) as f64 * 0.8;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 - (slack as f64 * 0.3).min(9.0);
            if slack % 5 == 0 { score -= 2.0; } // harmonic alignment
        } else {
            // next item cannot use this residual: penalize proportionally
            score += ((next_item_size - pr) as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has high raw residual; keep it
    // attractive only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9
            + (mean_residual - (bin_capacity as f64) / 2.0) * 0.3
            + progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: must open
        }
        if next_item_size > bin_capacity / 2 {
            score += 3.0; // large next item: prefer fresh bin slightly
        }
    }

    // Coarse band tiebreak: prefer bins whose residual band matches item size band.
    let band = item_size / 20;
    if coarse >= band { score -= 1.5; } else { score += 1.5; }

    // Slight preference to fill fuller bins as stream progresses.
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

