    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold the minimum item (1) is pure waste;
    // residuals below a "useful threshold" scale super-linearly.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr < dead_threshold {
        // quadratic dead-space penalty for tiny gaps
        score += (dead_threshold - pr) * (dead_threshold - pr) * 0.5;
    }

    // Reward tight fits (post_residual near zero) with a strong bonus.
    if pr == 0.0 {
        score -= 50.0;
    } else if pr <= 5.0 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few bins fit.
    let fbc = fitting_bins_count as f64;
    if fitting_bins_count == 1 {
        // last chance: strongly favor using this bin before opening a new one
        score -= 30.0;
    } else {
        // mild pressure proportional to open bins
        score += (open_bins_count as f64) * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n - pr).abs() < f64::EPSILON {
            score -= 25.0;
        } else if n <= pr {
            score -= 5.0 * (1.0 - (pr - n) / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving a gap it can't use
            score += 3.0;
        }
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e. consuming a large residual) helps normalize bin states.
    score -= (mean_residual - pr) * 0.2;

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in the stream or when
        // many bins are already open and the current fit is poor.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if pr > 40.0 { 1.0 } else { 0.0 };
        score += 40.0 - 20.0 * progress + 10.0 * poor_fit * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

