    // Smooth polynomial coupling of post_residual with progress.
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (0.5 + progress) * 8.0;

    // Exact-fill bonus for the current item (residual fully consumed).
    if bin_residual == item_size {
        score -= 300.0;
    }

    // Three-step chaining — reward residuals that can host next item
    // plus a small extra, keeping chains alive longer.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        if rem == 0 {
            score -= 100.0;
        } else if rem <= 6 {
            score -= 40.0 - 5.0 * rem as f64;
        }
    }

    // Dead-space penalty scaled by remaining stream length —
    // waste matters more when many items still must be placed.
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += (1.0 - progress) * 25.0;
    }

    // Prime dead space (1..=8): unusable slivers, worse late.
    if post_residual >= 1 && post_residual <= 8 {
        score += (1.0 - progress) * 30.0 + 5.0;
    }

    // Homogeneity: keep residuals near the running mean.
    let mean_diff = (mean_residual - pr).abs();
    score += 0.15 * mean_diff;

    // Graded dead-zone ramp over 9..=15: residuals near 9 (nearly stranded)
    // penalized more than residuals near 15 (more recoverable).
    if post_residual >= 9 && post_residual <= 15 {
        let depth = (15 - post_residual) as f64 / 6.0;
        score += 4.0 + depth * (10.0 + (1.0 - progress) * 14.0);
    }

    // Near-miss guard — residual just below the next item by 1..=4
    // strands almost the whole residual; penalize with progress weighting.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score += (30.0 - 6.0 * gap as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Two-item lookahead — residual can host next item AND still leaves
    // room for a typical small follow-up (mean residual as proxy).
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        let typical = mean_residual.max(6.0) as u32;
        if rem >= typical && rem <= typical + 10 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // MUTATION: perfect two-item closure — if the current item exactly
    // consumes the residual AND the post residual exactly matches the next
    // item, this is a flawless chain; reinforce beyond the sum of parts.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual == item_size {
        score -= 200.0;
    }

    // MUTATION: waste-fraction term — penalize stranded slack proportionally
    // to how much of the bin's original capacity it represents, weighted by
    // remaining stream. Catches mid-range dead zones (16..=30) the ladder
    // and dead-zone ramp both miss.
    if post_residual >= 16 && post_residual < next_item_size.max(1) {
        let waste_frac = pr / cap;
        score += waste_frac * 220.0 * (1.0 - progress);
    }

    // MUTATION: recoverable slack bonus — residuals in 16..=40 that CAN
    // still host the next item are partially recoverable; soften the
    // consolidation pressure there so we don't dump them prematurely.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual >= 16 && post_residual <= 40 {
        score -= 18.0 * (1.0 - progress);
    }

    // New empty bin candidate: pay a cost so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 110.0 + 0.6 * mean_residual + 80.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_cost -= 30.0;
        }
        // Fresh bin can host both current and next item exactly.
        if next_item_size > 0 && post_residual < next_item_size
            && item_size + next_item_size <= bin_capacity {
