        }
        if open_bins_count <= 2 {
            new_bin_cost -= 15.0;
        }
        if progress < 0.15 {
            new_bin_cost -= 20.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let orphan = next_item_size - post_residual;
            if orphan >= 15 {
                new_bin_cost -= 25.0;
            }
        }
        if fitting_bins_count >= 3 {
            new_bin_cost += 20.0;
        }
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 25 {
            new_bin_cost -= 18.0;
        }
        if progress > 0.5 && pr > cap / 3.0 && fitting_bins_count <= 2 {
            new_bin_cost -= 12.0;
        }
        // Awkward 9..=15 dead zone: full slack beats stranded slivers.
        if post_residual >= 9 && post_residual <= 15 && fitting_bins_count <= 2 {
            new_bin_cost -= 20.0;
        }
        // Prefer a fresh bin when the orphan residual falls in the prime
        // dead zone 1..=8 AND many items remain.
        if post_residual >= 1 && post_residual <= 8 && (1.0 - progress) > 0.3 {
            new_bin_cost -= 16.0;
        }
        // MUTATION: extended orphan dead zone 16..=30 — a mid-range stranded
        // residual with a large orphan also justifies a fresh bin early on.
        if post_residual >= 16 && post_residual <= 30 && fitting_bins_count <= 2 && (1.0 - progress) > 0.4 {
            new_bin_cost -= 14.0;
        }
        // MUTATION: fresh-bin pairing bonus — if the fresh bin could take
        // current + next + a typical third item, it's a strong chain start.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let after_two = bin_capacity - item_size - next_item_size;
            if after_two as f64 >= mean_residual.max(6.0) {
                new_bin_cost -= 12.0;
            }
        }
        // Late-stream guard: opening new bins very late is rarely recoverable.
        if progress > 0.85 {
            new_bin_cost += 35.0 * (progress - 0.85) / 0.15;
        }
        score += new_bin_cost;
    }

    // Mild penalty for spreading across many bins, stronger late.
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
