        let rem = post_residual - next_item_size;
        if rem <= 12 {
            score -= 90.0 - 5.0 * rem as f64;
        } else {
            score -= 25.0 / (rem as f64).sqrt();
        }
        // Chain continuation: residual can host next item plus a typical follow-up.
        let typical = mean_residual.max(6.0) as u32;
        if rem >= typical && rem <= typical + 10 {
            score -= 20.0 * (1.0 - progress);
        }
    } else if next_item_size > 0 {
        let gap = next_item_size - post_residual;
        score += 10.0 + 0.5 * gap as f64;
        // Near-miss guard: residual just below next item strands slack.
        if gap <= 4 {
            score += (25.0 - 5.0 * gap as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
    }

    // Compare against mean residual: prefer tighter-than-average bins.
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
        score -= 0.2 * (mean_residual - pr);
    }

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 4.0;
