pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes of 10
    // (capacity fractions). Small residues in "good" classes are rewarded.
    let cls = (post_residual / 10) as f64;
    let rem = (post_residual % 10) as f64;
    // Fractional leftover inside a class is dead space: penalize it.
    score += rem * 0.7;

    // Non-linear reward for tight fits: perfect fill strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic coupling: if next item exactly fills the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the residual at all: penalize waste
            let waste = post_residual as f64;
            score += waste * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 55.0 + open_bins_count as f64 * 2.0;
        // If current item leaves a large residual anyway, opening fresh
        // is comparable; soften penalty when item is large.
        if item_size >= 70 {
            score -= 30.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // If the item would fit an existing bin with near-perfect fill,
        // discourage the new bin (existing tight fit already gets bonus).
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins first keeps
    // tight bins available for small items).
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score += (res_f - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - res_f) * 0.15;
    }

    // Harmonic class bonus: residuals that are multiples of 20 pair well
    // with mid-size items.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Exact 2-step match: leave exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1200.0;
    }

    // Near match: next item fits and leaves only a tiny sliver.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step_left = post_residual - next_item_size;
        if two_step_left <= 12 {
            score -= 450.0 - 30.0 * two_step_left as f64;
        } else {
            score -= 60.0 / (two_step_left as f64).sqrt();
        }
    }

    // Penalize when next item cannot use the remaining space.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        score += 20.0 + 0.6 * gap as f64;
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Near-miss guard for gaps 1..=4 strands the residual.
        if gap <= 4 {
            score += (30.0 - 6.0 * gap as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Tight-fit ladder: reward nearly perfect fills.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 160.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Prefer bins tighter than the running average.
    score -= 0.5 * (mean_residual - pr);

    // Late-stream consolidation pressure on loose space.
    score += progress * (pr * 0.35);

    // Smooth polynomial coupling of post_residual with progress.
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (0.5 + progress) * 8.0;

    // Exact-fill bonus for the current item.
    if bin_residual == item_size {
        score -= 300.0;
    }

    // Three-step chaining reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        if rem == 0 {
            score -= 100.0;
        } else if rem <= 6 {
            score -= 40.0 - 5.0 * rem as f64;
        }
    }

    // Dead-space penalty scaled by remaining stream length.
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += (1.0 - progress) * 25.0;
    }

    // Prime dead space (1..=8): unusable slivers, worse late.
    if post_residual >= 1 && post_residual <= 8 {
        score += (1.0 - progress) * 30.0 + 5.0;
    }

    // Homogeneity: keep residuals near the running mean.
    let mean_diff = (mean_residual - pr).abs();
    score += 0.15 * mean_diff;

    // Graded dead-zone ramp over 9..=15.
    if post_residual >= 9 && post_residual <= 15 {
        let depth = (15 - post_residual) as f64 / 6.0;
        score += 4.0 + depth * (10.0 + (1.0 - progress) * 14.0);
    }

    // Two-item chain continuation — residual hosts next item and
    // still leaves room for a typical follow-up sized via mean residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        let typical = mean_residual.max(6.0) as u32;
        if rem >= typical && rem <= typical + 10 {
