    }

    // MUTATION: three-item lookahead — if residual can host next item plus
    // a mid-sized follow-up (half the mean residual), reward continuation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        let mid = ((mean_residual * 0.5).max(4.0)) as u32;
        if rem >= mid && rem <= mid + 6 {
            score -= 18.0 * (1.0 - progress) + 6.0;
        }
    }

    // New empty bin candidate: costly, only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 110.0 + 0.6 * mean_residual + 80.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
