        }
        // Late-stream guard: opening new bins very late is rarely recoverable.
        if progress > 0.85 {
            new_bin_cost += 35.0 * (progress - 0.85) / 0.15;
        }
        score += new_bin_cost;
    }

    // Mild penalty for spreading across many bins, stronger late.
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize gaps that are too small to be useful later (below ~10 or
        // below the smallest plausible item), scaled non-linearly.
        if post_residual < 10 {
            score += 40.0 * (10.0 - dead) / 10.0;
        } else if post_residual < 20 {
            score += 12.0 * (20.0 - dead) / 10.0;
        } else if post_residual < 35 {
            score += 4.0 * (35.0 - dead) / 15.0;
        }
        // Bonus (subtracted) if the leftover gap exactly accommodates the
        // lookahead item, avoiding a near-certain future dead space.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 8.0;
        }
    } else {
        // Perfect fill is the ideal outcome.
        score -= 30.0;
    }

    // Tight-fit reward: filling most of the residual is desirable.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than leaving many partially-filled bins around.
    let open_pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score -= open_pressure * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless the item
    // is large (then a fresh bin gives maximal future flexibility).
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 6.0;
        } else if item_size <= 30 {
            score += 10.0;
        } else {
            score += 3.0;
        }
        // Late in the stream, opening new bins wastes capacity; discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for bins already below mean residual (balancing).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

