        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 55.0; // perfect chain: item then next item fills bin exactly
        } else if diff <= 5 {
            score -= 30.0;
        } else if diff <= 10 {
            score -= 15.0;
        } else {
            score += diff as f64 * 0.15; // penalize leftover far from next item
        }
        // If next item cannot fit even in a fresh bin region, damp lookahead reward.
        if next_item_size > bin_capacity {
            score += 10.0;
        }
    }

