        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.25;
        } else {
            score += (pr - mean_residual) * 0.35;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits this item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 45.0;
