    score += 25.0 * dev * dev;

    // Size-dependent smooth coupling: large items prefer tight bins
    score -= 20.0 * it_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 22.0 * tightness * tightness;

    // Exact 2-step match: leave exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1200.0;
    }

    // Near match: next item fits and leaves only a tiny sliver.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step_left = post_residual - next_item_size;
        if two_step_left <= 12 {
            score -= 450.0 - 30.0 * two_step_left as f64;
        } else {
            score -= 60.0 / (two_step_left as f64).sqrt();
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 160.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Penalize when next item cannot use the remaining space.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        score += 20.0 + 0.6 * gap as f64;
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Near-miss guard for gaps 1..=4 strands the residual.
        if gap <= 4 {
            score += (30.0 - 6.0 * gap as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Penalize leaving residuals that no plausible future item can use.
    if post_residual > 0 {
        let waste_risk = 1.0 - tightness;
        score += 8.0 * waste_risk * (pr / cap);
    }

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Prefer bins tighter than the running average.
    score -= 0.5 * (mean_residual - pr);

    // Late-stream consolidation pressure on loose space.
    score += progress * (pr * 0.35);

    // Smooth polynomial coupling of post_residual with progress.
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (0.5 + progress) * 8.0;

    // Exact-fill bonus for the current item.
    if bin_residual == item_size {
        score -= 300.0;
    }

    // Three-step chaining reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        if rem == 0 {
            score -= 100.0;
        } else if rem <= 6 {
            score -= 40.0 - 5.0 * rem as f64;
        }
    }

    // Dead-space penalty scaled by remaining stream length.
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += (1.0 - progress) * 25.0;
    }

    // Prime dead space (1..=8): unusable slivers, worse late.
    if post_residual >= 1 && post_residual <= 8 {
        score += (1.0 - progress) * 30.0 + 5.0;
    }

    // Homogeneity: keep residuals near the running mean.
    let mean_diff = (mean_residual - pr).abs();
    score += 0.15 * mean_diff;

    // Graded dead-zone ramp over 9..=15.
    if post_residual >= 9 && post_residual <= 15 {
        let depth = (15 - post_residual) as f64 / 6.0;
        score += 4.0 + depth * (10.0 + (1.0 - progress) * 14.0);
    }

    // Two-item chain continuation: residual hosts next item and still leaves
    // room for a typical follow-up sized via mean residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        let typical = mean_residual.max(6.0) as u32;
        if rem >= typical && rem <= typical + 10 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // New empty bin candidate: costly, only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 110.0 + 0.6 * mean_residual + 80.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_cost -= 30.0;
        }
        if next_item_size > 0 && post_residual < next_item_size
            && item_size + next_item_size <= bin_capacity {
            new_bin_cost -= 40.0;
        }
        if open_bins_count <= 2 {
            new_bin_cost -= 15.0;
        }
        if progress < 0.15 {
            new_bin_cost -= 20.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let orphan = next_item_size - post_residual;
            if orphan >= 15 {
                new_bin_cost -= 25.0;
            }
        }
        if fitting_bins_count >= 3 {
            new_bin_cost += 20.0;
        }
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 25 {
            new_bin_cost -= 18.0;
        }
        if progress > 0.5 && pr > cap / 3.0 && fitting_bins_count <= 2 {
            new_bin_cost -= 12.0;
        }
        if post_residual >= 9 && post_residual <= 15 && fitting_bins_count <= 2 {
            new_bin_cost -= 20.0;
        }
        // Fresh capacity beats stranded 1..=8 slivers while many items remain.
        if post_residual >= 1 && post_residual <= 8 && (1.0 - progress) > 0.3 {
            new_bin_cost -= 16.0;
        }
        // When the item nearly fills a fresh bin exactly, opening new is clean.
        if item_size * 20 >= bin_capacity * 17 {
            new_bin_cost -= 12.0;
        }
        // Late-stream guard: opening new bins very late is rarely recoverable.
        if progress > 0.85 {
            new_bin_cost += 35.0 * (progress - 0.85) / 0.15;
        }
        // MUTATION: with many fitting bins, opening new is even more wasteful.
        if fitting_bins_count >= 4 {
            new_bin_cost += 15.0 * (fitting_bins_count as f64 - 3.0);
        }
