    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are "unusable" for
    // typical items -> heavy penalty so we never strand a sliver.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 12.0; // still risky small gap
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the would-be
    // residual, strongly favor this bin; if it can't fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over spreading out; also penalize bins whose residual is far above mean.
    score += open_bins_count as f64 * 1.5;
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

