        score += 35.0 + open_bins_count as f64 * 2.0;
        if post_residual >= 1 && post_residual <= 9 {
            score -= 55.0; // but a fresh bin avoids sliver creation elsewhere
        }
    }

    // Early in the stream, be slightly more willing to open bins for
    // flexibility; late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

