        }
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 25 {
            new_bin_cost -= 18.0;
        }
        if progress > 0.5 && pr > cap / 3.0 && fitting_bins_count <= 2 {
            new_bin_cost -= 12.0;
        }
        if post_residual >= 9 && post_residual <= 15 && fitting_bins_count <= 2 {
            new_bin_cost -= 20.0;
        }
        // Fresh capacity beats stranded 1..=8 slivers while many items remain.
        if post_residual >= 1 && post_residual <= 8 && (1.0 - progress) > 0.3 {
            new_bin_cost -= 16.0;
        }
        // Item nearly fills a fresh bin exactly: opening new is cheap and clean.
        if item_size * 20 >= bin_capacity * 17 {
            new_bin_cost -= 12.0;
        }
        // MUTATION: large items pair well with fresh capacity when the next
        // item is also large — pair-packing lookahead.
        if item_size >= bin_capacity / 2 && next_item_size >= bin_capacity / 3 {
            new_bin_cost -= 22.0;
        }
