    // If next item fits into post-residual, mildly reward keeping that option.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item would NOT fit here but fits a tighter alternative, penalize hoarding space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
