pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space.
    let post = post_residual as u32;
    // Class width 10 -> harmonic classes 0..=10 (0 = perfect fit).
    let post_class = post / 10;

    // Reward near-perfect fits strongly (non-linear).
    if post == 0 {
        score -= 200.0;
    } else if post <= 5 {
        score -= 120.0 - (post as f64) * 10.0;
    } else if post <= 10 {
        score -= 60.0 - (post as f64) * 2.0;
    } else if post <= 20 {
        score -= 20.0 - (post as f64) * 0.5;
    }

    // Penalize dead-space classes that are hard to fill by typical items:
    // leftovers in (0,10) can rarely host items >=10 unless tiny items exist.
    if post > 0 && post < 10 {
        score += 15.0;
    }
    // Class 10..20 is moderately useful; class >50 keeps bin flexible.
    if post >= 10 && post < 20 {
        score -= 5.0;
    }
    if post >= 50 {
        score -= 8.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Great: chain placement possible; reward tighter chains.
            let slack = post - next_item_size;
            score -= 30.0 - (slack as f64) * 0.5;
            if slack == 0 {
                score -= 40.0; // exact two-item completion
            }
        } else {
            // Next item won't fit here; mild penalty scaled by overflow size.
            let over = next_item_size - post;
            score += (over as f64).min(50.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // More open bins with slack -> prefer reusing them.
        score += open_bins_count as f64 * 2.0;
        // If mean residual comfortably fits the item, opening new bin is wasteful.
        if (mean_residual - item_size as f64) > 10.0 {
            score += 25.0;
        }
        // Late in stream, opening new bins is rarely recovered.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If next item is huge, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Fractional capacity coupling: prefer bins whose fill ratio after placement
    // crosses harmonic thresholds (50%, 75%, 90%).
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill >= 0.9 {
        score -= 25.0;
    } else if fill >= 0.75 {
        score -= 15.0;
    } else if fill >= 0.5 {
        score -= 8.0;
    }

    // Mild preference for fuller bins overall (best-fit flavor).
    score -= (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
