    score += open_bins_count as f64 * (0.4 + 0.65 * progress);

    // Mid-range residual reuse bonus: residuals near common item sizes stay useful.
    if pr > 20 && pr <= 45 {
        score -= 10.0 + 0.15 * (45.0 - prf);
    }

