    let half = bin_capacity / 2;         // 50
    let three_quarter = 3 * quarter;     // 75

    // Reward tight fits: post_residual in the smallest harmonic class.
    if post_residual < quarter {
        score -= 12.0;
    } else if post_residual < half {
        score -= 4.0;
    } else if post_residual < three_quarter {
        score += 3.0;
    } else {
        score += 8.0; // leaving more than 3/4 empty is wasteful
    }

    // Exact modulo harmony: post_residual divisible by small integers
    // (e.g. 5, 10) tends to be reusable by typical item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 5.0;
        } else if post_residual % 5 == 0 {
            score -= 2.5;
        }
    } else {
        // Perfect fill is ideal.
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // Harmonic class of the residual after the lookahead item.
            if nxt_post < quarter {
                score -= 6.0;
            } else if nxt_post < half {
                score -= 1.0;
            } else {
                score += 2.0;
            }
        } else {
            // Next item won't fit here; slight penalty unless this is
            // the only fitting bin (last-chance effect).
            if fitting_bins_count > 1 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current
    // open bins are badly fragmented (mean residual large relative to
    // item size) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 25.0
            - 10.0 * fragmentation
            - 8.0 * progress
            - (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mild preference for fuller bins (small bin_residual before placing).
    score += 0.02 * (bin_capacity - bin_residual) as f64;

    // Slight penalty for spreading across too many open bins.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fill: heavily reward exact zero residual.
    if pr == 0 {
        score -= 1000.0;
    }

    // Exact 2-step lookahead: leave exactly room for next item.
    if next_item_size > 0 && pr == next_item_size {
        score -= 800.0;
    } else if next_item_size > 0 && pr > next_item_size {
        let two_step_left = pr - next_item_size;
        if two_step_left <= 14 {
            score -= 380.0 - 24.0 * two_step_left as f64;
        } else {
            score -= 55.0 / (two_step_left as f64).sqrt();
        }
    } else if next_item_size > 0 && pr < next_item_size {
        let gap = (next_item_size - pr) as f64;
        score += 15.0 + 0.5 * gap;
        if gap <= 5 {
            score += (32.0 - 6.0 * gap) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Harmonic class residuals are reusable.
    if pr % 10 == 0 && pr > 0 { score -= 14.0; }
    if pr % 20 == 0 && pr > 0 { score -= 7.0; }
    if pr % 25 == 0 && pr > 0 { score -= 7.0; }
    if pr % 50 == 0 && pr > 0 { score -= 9.0; }

    // Dead-space tiers: tiny slivers are hard to reuse.
    if pr > 0 && pr < 10 {
        score += 62.0 + (1.0 - progress) * 26.0;
    } else if pr > 0 && pr < 20 {
        score += 16.0 + (1.0 - progress) * 11.0;
    }

    // Fraction-of-capacity thresholds.
    let frac = prf / cap;
    if frac > 0.5 { score -= 11.0; }
    else if frac > 0.25 { score -= 4.0; }
    else if pr > 0 { score += 8.0; }

    // Tight-fit ladder.
    if pr > 0 && pr <= 5 { score -= 130.0; }
    else if pr > 5 && pr <= 9 { score -= 60.0; }

    // Exact fill of current bin residual by this item.
    if bin_residual == item_size {
        score -= 260.0;
    }

    // Homogeneity coupling with running mean residual.
    score -= 0.45 * (mean_residual - prf);

    // Late-stream consolidation pressure on loose space.
    score += progress * prf * 0.32;

    // Smooth polynomial coupling of post_residual with progress.
    let norm_pr = prf / cap;
    score += norm_pr * norm_pr * (0.5 + progress) * 9.0;

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 190.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: costly unless it enables clean chains.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 112.0 + 0.6 * mean_residual + 72.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_cost -= 30.0;
        }
        if next_item_size > 0 && pr < next_item_size && item_size + next_item_size <= bin_capacity {
            new_bin_cost -= 42.0;
        }
        if open_bins_count <= 2 {
            new_bin_cost -= 16.0;
        }
        if progress < 0.15 {
            new_bin_cost -= 20.0;
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size {
            let orphan = next_item_size - pr;
            if orphan >= 15 {
                new_bin_cost -= 26.0;
            }
        }
        if fitting_bins_count >= 3 {
            new_bin_cost += 20.0;
        }
        if fitting_bins_count == 1 && pr > 0 && pr < 25 {
            new_bin_cost -= 18.0;
        }
        if progress > 0.5 && prf > cap / 3.0 && fitting_bins_count <= 2 {
            new_bin_cost -= 13.0;
        }
        if pr >= 1 && pr <= 8 && (1.0 - progress) > 0.3 {
            new_bin_cost -= 17.0;
        }
        if item_size * 20 >= bin_capacity * 17 {
            new_bin_cost -= 12.0;
        }
        if progress > 0.85 {
            new_bin_cost += 35.0 * (progress - 0.85) / 0.15;
        }
        // Pair-chain bonus: fresh bin can host item plus a mid-size companion.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && next_item_size >= item_size / 2 {
            new_bin_cost -= 8.0;
        }
        // Triple-chain lookahead — fresh bin hosting item + next + a plausible
        // follow-up companion reduces dead space when next_item is small.
        if next_item_size > 0 && next_item_size <= 20 {
            let triple = item_size + next_item_size;
            if triple <= bin_capacity && bin_capacity - triple >= 10 {
                new_bin_cost -= 10.0;
            }
        }
        // Opening a bin to absorb an item that fits NO open bin tightly
        // (all fits leave > 30 slack) is cheaper than fragmenting.
        if fitting_bins_count >= 1 && item_size * 3 < bin_residual {
            new_bin_cost -= 6.0;
        }
        // NEW: refine — when the best open fit would leave a near-miss sliver
        // (residual just below next_item), a fresh bin with room for item+next
        // is strongly preferable; deepens the dead-space fix.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let mut worst_miss = 0.0f64;
            // proxy: current bin residual is representative of fit quality
            let miss = (bin_residual - item_size) as f64;
            if miss > 0.0 && miss < next_item_size as f64 {
                worst_miss = next_item_size as f64 - miss;
            }
            if worst_miss > 0.0 && worst_miss <= 15.0 {
                new_bin_cost -= 4.0 + 0.8 * (15.0 - worst_miss);
            }
        }
        // NEW: fresh-bin slack after hosting item+next should be small or
        // harmonically reusable; penalize fresh bins that strand large odd slack.
        if next_item_size > 0 {
            let after_pair = bin_capacity - item_size - next_item_size;
            if item_size + next_item_size <= bin_capacity {
                if after_pair > 0 && after_pair < 12 {
                    new_bin_cost -= 14.0; // tiny slack is acceptable late
                } else if after_pair >= 12 && after_pair < 30 {
                    new_bin_cost += 10.0; // mid slack strands capacity
                }
            }
        }
        score += new_bin_cost;
    }

    // Consolidation pressure when many bins are open.
    if open_bins_count > 4 && prf < 0.3 * cap && pr > 0 {
        score -= 7.0;
    }

    // Spreading penalty, stronger late.
    score += open_bins_count as f64 * (0.4 + 0.65 * progress);

    // Mid-range residual reuse bonus: residuals near common item sizes stay useful.
    if pr > 20 && pr <= 45 {
        score -= 10.0 + 0.15 * (45.0 - prf);
    }

    // Penalize leaving residual just below next_item_size by a small margin —
    // near-miss slivers waste capacity (dead-space refinement, sharpened).
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let miss = (next_item_size - pr) as f64;
        if miss > 5.0 && miss <= 12.0 {
            score += 20.0 * (1.0 - miss / 12.0);
        } else if miss > 12.0 && miss <= 20.0 {
            // NEW: extended near-miss band, weaker, grows late when fewer
            // chances remain to fix stranded slack.
            score += 3.0 + 5.0 * progress;
        }
    }

    // NEW: reward residuals that exactly match small common item sizes,
    // improving chain reuse of leftover space.
    if pr > 0 && pr <= 30 && (pr % 5 == 0) {
        score -= 6.0 + 0.2 * pr as f64;
    }

    score
}

