pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    // Penalize post_residuals that fall below the plausible minimum item size,
    // with a sharply increasing penalty as the gap approaches zero.
    let pr = post_residual as f64;
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else if post_residual < 35 { 0.25 } else { 0.0 };
        score += dead * 60.0 * (1.0 - pr / 100.0);
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to current residual (best-fit flavor).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 20.0;

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading; when few bins are open,
    // allow slightly looser fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (pr / 100.0);

    // If this bin is the only one that fits, strongly prefer using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are large
    // and fragmented (mean residual high means poor fits available).
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            // No open bin can tightly host such items well; new bin is fine.
            score -= 5.0;
        } else {
            // Prefer existing bins when they leave comparable leftovers.
            score += 15.0 + (mean_gap * 0.3).min(40.0);
        }
        // Late in the stream, avoid opening bins aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

