    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins tighter than the average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or no good fit exists
    if bin_residual == bin_capacity {
        score += 120.0;
