        // Final: use new_bin_score blended with post-residual baseline.
        score = 0.5 * new_bin_score + 0.5 * (post_residual as f64);
    }

    // Global state: many open bins with high mean residual -> discourage
    // wasting space in existing bins, encourage consolidation.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 0.05 * (mean_residual - 30.0);
    }

    // Time horizon: late in the stream, prefer minimizing bin count strictly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 5.0 * fill_ratio;
    }

    score
}

