}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: reward tight fit via non-linear polynomial in post_residual
    let mut score = pr_norm.powf(2.0) * 30.0 + pr_norm * 10.0;

    // Smooth coupling: tightness valued more as stream progresses
    score -= (1.0 - pr_norm).powf(3.0) * (20.0 + 40.0 * progress * progress);

    // Penalize bins whose residual deviates from mean residual (dead-space spread)
    score += ((pr - mean_residual) / cap).powi(2) * 8.0;

    // Last-chance bonus (smooth): strongly favor the only fitting bin
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= last_chance * (25.0 + 30.0 * progress);

    // Lookahead coupling: bonus if next item fits in post_residual
    if next_item_size > 0 {
        let next_fits = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let next_tight = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= next_fits * next_tight.max(0.0) * 15.0;
    } else {
