        score += 30.0; // dead-space penalty
    } else if post_residual <= 50 {
        score -= 15.0; // still usable for medium items
    } else if post_residual <= 75 {
        score -= 25.0; // highly reusable class
    }

    // Integer-division coupling: does post_residual exactly accommodate next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 300.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let rem = post_residual - nxt;
            score -= 40.0 - (rem / cap) * 20.0; // lookahead fits, mild reward by slack
        } else {
            // next item cannot use this residual: residual value drops
            score += (nxt - post) * 0.5;
        }
        // Harmonic alignment: next item is a divisor-friendly size (20/25/50)
        if next_item_size == 50 || next_item_size == 25 || next_item_size == 20 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.25 * (bin_residual as f64 - item_size as f64);
    }

    // New-bin candidate handling: empty bin should lose unless current fit is bad.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins are open and mean
        // residual is high (we are wasting space overall).
        score += 90.0 + open_bins_count as f64 * 2.0;
        if mean_residual > cap * 0.5 {
            score += 40.0;
