        // Early in stream, opening bins is cheaper (need spread of anchors).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 70.0;
    }

    // Mean-residual coupling: prefer bins deviating favorably from mean.
    score -= (mean_residual - post) * 0.3;

    // Exact harmonic thresholds via integer division on post_residual:
    // multiples of 25 are "aligned" leftovers that pair well with future items.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    score
}

