    if pr % 20 == 0 && pr > 0 { score -= 7.0; }
    if pr % 25 == 0 && pr > 0 { score -= 7.0; }
    if pr % 50 == 0 && pr > 0 { score -= 9.0; }

    // Dead-space tiers: tiny slivers are hard to reuse. Sharpened early-stream.
    if pr > 0 && pr < 10 {
        score += 62.0 + (1.0 - progress) * 30.0;
    } else if pr > 0 && pr < 20 {
        score += 16.0 + (1.0 - progress) * 11.0;
    }

    // Fraction-of-capacity thresholds.
    let frac = prf / cap;
    if frac > 0.5 { score -= 11.0; }
    else if frac > 0.25 { score -= 4.0; }
    else if pr > 0 { score += 8.0; }

    // Tight-fit ladder.
    if pr > 0 && pr <= 5 { score -= 130.0; }
    else if pr > 5 && pr <= 9 { score -= 60.0; }

    // Exact fill of current bin residual by this item.
    if bin_residual == item_size {
        score -= 260.0;
    }

    // Near-exact fill: item consumes >= 90% of residual — strong compaction.
    if item_size > 0 && bin_residual > item_size {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio >= 0.9 {
            score -= 120.0 * (fill_ratio - 0.9) / 0.1;
        }
    }

    // Homogeneity coupling with running mean residual.
    score -= 0.45 * (mean_residual - prf);

    // Late-stream consolidation pressure on loose space.
    score += progress * prf * 0.32;

    // Smooth polynomial coupling of post_residual with progress.
    let norm_pr = prf / cap;
    score += norm_pr * norm_pr * (0.5 + progress) * 9.0;

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 190.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: costly unless it enables clean chains.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 112.0 + 0.6 * mean_residual + 72.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_cost -= 30.0;
        }
        if next_item_size > 0 && pr < next_item_size && item_size + next_item_size <= bin_capacity {
            new_bin_cost -= 42.0;
        }
        if open_bins_count <= 2 {
            new_bin_cost -= 16.0;
        }
        if progress < 0.15 {
            new_bin_cost -= 20.0;
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size {
            let orphan = next_item_size - pr;
            if orphan >= 15 {
                new_bin_cost -= 26.0;
            }
        }
        if fitting_bins_count >= 3 {
            new_bin_cost += 20.0;
        }
        if fitting_bins_count == 1 && pr > 0 && pr < 25 {
            new_bin_cost -= 18.0;
        }
        if progress > 0.5 && prf > cap / 3.0 && fitting_bins_count <= 2 {
            new_bin_cost -= 13.0;
        }
        if pr >= 1 && pr <= 8 && (1.0 - progress) > 0.3 {
            new_bin_cost -= 17.0;
        }
        if item_size * 20 >= bin_capacity * 17 {
            new_bin_cost -= 12.0;
        }
        if progress > 0.85 {
            new_bin_cost += 35.0 * (progress - 0.85) / 0.15;
        }
        // Pair-chain bonus: fresh bin can host item plus a mid-size companion.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && next_item_size >= item_size / 2 {
            new_bin_cost -= 8.0;
        }
        // Triple-chain lookahead — fresh bin hosting item + next + a plausible
        // follow-up companion reduces dead space when next_item is small.
        if next_item_size > 0 && next_item_size <= 20 {
            let triple = item_size + next_item_size;
            if triple <= bin_capacity && bin_capacity - triple >= 10 {
                new_bin_cost -= 10.0;
            }
        }
        // Opening a bin to absorb an item that fits NO open bin tightly
        // (all fits leave > 30 slack) is cheaper than fragmenting.
        if fitting_bins_count >= 1 && item_size * 3 < bin_residual {
            new_bin_cost -= 6.0;
        }
        // NEW: when the best open-bin fit would leave a mid-range orphan
        // (15..40) and the item plus next item exactly tiles a fresh bin,
        // opening is strongly preferable — avoids stranded slivers.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            new_bin_cost -= 24.0;
        }
        // NEW: early-stream large items (>= 60% of capacity) pair poorly;
        // isolate them in fresh bins to keep open bins flexible.
        if progress < 0.4 && item_size * 5 >= bin_capacity * 3 {
            new_bin_cost -= 14.0;
        }
        // NEW: late-stream with few remaining items — fresh-bin cost grows
        // since the new bin may never be refilled.
        if progress > 0.9 && next_item_size == 0 {
            new_bin_cost += 60.0;
        }
        score += new_bin_cost;
    }

    // Consolidation pressure when many bins are open.
    if open_bins_count > 4 && prf < 0.3 * cap && pr > 0 {
        score -= 7.0;
    }

    // Spreading penalty, stronger late.
    score += open_bins_count as f64 * (0.4 + 0.65 * progress);

    // Mid-range residual reuse bonus: residuals near common item sizes stay useful.
    if pr > 20 && pr <= 45 {
        score -= 10.0 + 0.15 * (45.0 - prf);
    }

    // Penalize leaving residual just below next_item_size — near-miss slivers
    // waste capacity (dead-space refinement), scaled by remaining stream.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let miss = (next_item_size - pr) as f64;
        if miss > 5.0 && miss <= 12.0 {
            score += 18.0 * (1.0 - miss / 12.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // NEW: reward residuals that exactly match next_item_size's harmonic
    // complements — a residual reusable by the *following* item class.
    if next_item_size > 0 && pr > next_item_size {
        let rem = pr - next_item_size;
        if rem % 10 == 0 && rem > 0 {
            score -= 12.0;
        }
    }

    // NEW: mild penalty when post residual cannot host the mean item size
    // implied by mean residual — stranded space detection.
    if pr > 0 && prf < mean_residual * 0.5 && pr < 30 {
        score += 9.0 * (1.0 - prf / 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
