    // Homogeneity coupling with running mean residual.
    score -= 0.45 * (mean_residual - prf);

    // Late-stream consolidation pressure on loose space.
    score += progress * prf * 0.32;

    // Smooth polynomial coupling of post_residual with progress.
    let norm_pr = prf / cap;
    score += norm_pr * norm_pr * (0.5 + progress) * 9.0;

    // Last-chance bin.
    if fitting_bins_count == 1 {
