        score += remaining * remaining * prf * 0.22;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect chain into the following item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        // Exact match: strong reward (chain completes perfectly).
        if diff < 0.5 {
            score -= 60.0;
        } else if diff <= 10.0 {
            // Near match: scaled reward.
            score -= 45.0 * (1.0 - diff / 10.0);
        } else if post < nxt {
            // Next item won't fit here: mild penalty for stranding space.
            score += 8.0;
        } else {
            // Next item fits but leaves a new gap: penalize leftover gap size.
            score += 0.25 * (post - nxt);
        }

        // Bonus if placing now AND next item fits too: two-for-one chain.
        if nxt <= post {
            score -= 10.0;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving more than the average residual wastes capacity.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // badly fragmented (few fitting bins, high mean residual waste).
    if bin_residual == bin_capacity {
        let fragmentation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 - 55.0 * fragmentation - 0.2 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for tighter fits overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64 * 0.0
        + 0.05 * item_size as f64;

    score
}

