pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (time horizon)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward filling bins well
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Penalize small post-residuals that are useless dead space
    // (post_residual small but nonzero is bad; zero is perfect)
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        let dead_useful = (next_item_size as f64) <= post_residual as f64 && next_item_size > 0;
        if !dead_useful {
            score += 25.0 * (1.0 - dead);
        } else {
            score -= 15.0; // next item fits in the leftover: chain placement
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: prefer the tightest one; add mild penalty scaled by competition
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global pressure: few open bins relative to progress -> be frugal, prefer reusing
    let pressure = open_bins_count as f64 / (1.0 + t * 20.0);
    if bin_residual < bin_capacity {
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: open only when residuals are fragmented or item is large
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let open_bonus = if item_size >= 60 {
            -10.0
        } else if mean_residual < item_size as f64 {
            -8.0
        } else {
            5.0 + fragmentation * 0.1
        };
        score += open_bonus + t * 10.0; // late stream: discourage new bins
    }

    // Lookahead coupling: if next item is huge, keep large residuals intact
    if next_item_size >= 50 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Mild nonlinearity on residual waste
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 20.0);

