        if frac < 0.05 {
            score += 25.0; // tiny unusable sliver: dead space
        } else if frac < 0.15 {
            score += 10.0;
        } else if frac < 0.35 {
            score -= 5.0; // mid residual: reusable
        } else {
            score -= 12.0; // large residual keeps flexibility
        }

        // Modulo-10 harmonic class: residuals in "round" classes are easier to fill later.
        let class = post_residual % 10;
        if class == 0 {
            score -= 6.0;
        } else if class >= 7 {
            score += 4.0; // awkward class
        }

        // Lookahead coupling: can the next item land in the post residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 8.0;
                // exact two-item fill bonus
                if next_item_size == post_residual {
                    score -= 15.0;
                }
                // harmonic alignment: next item leaves a round residual again
                if (post_residual - next_item_size) % 10 == 0 {
                    score -= 4.0;
