    if bin_residual == bin_capacity {
        // new bin baseline: roughly the mean residual of the system
        score = 50.0 + mean_residual * 0.3 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits, opening new bin is correct
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
