        // bin, opening it is essentially free (avoids fragmenting an open bin).
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            new_bin_cost -= 55.0;
        }
        // NEW: late stream with big item — prefer fresh bin over wrecking a
        // reusable open residual when the item leaves < 8 slack anywhere.
        if progress > 0.6 && item_size > bin_capacity / 2 {
            new_bin_cost -= 9.0 + 12.0 * (progress - 0.6);
        }
        // NEW: penalize opening when open bins retain large, reusable residuals.
        if mean_residual > 0.35 * cap {
            new_bin_cost += 14.0 * (mean_residual / cap - 0.35);
        }
