            score -= 6.0 * reuse * (1.0 - progress);
        }
    }

    // NEW: two-item chain into an open bin — if item + next exactly consumes the
    // bin residual, this is a perfect chain; reward strongly.
    if next_item_size > 0 && pr == item_size + next_item_size {
        score -= 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (below the minimum size of 1 => anything >0 is "usable" in
    // theory, but tiny gaps under ~10 are practically dead) get a heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    } else {
        // Larger residuals are flexible: mild reward for keeping room.
        score -= 5.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual tightly matches the item (low waste fraction).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // rather than spreading; penalize candidates when bin count is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.8 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: base cost of opening a bin, modulated by whether the
    // current item would leave a bad gap in existing bins and by lookahead.
    if bin_residual == bin_capacity {
        score = 120.0;
        // If no existing bin fits well (post_residual small in all fits),
        // opening fresh is fine; if lookahead item fits in the fresh bin
        // nicely with the current one, encourage it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // Late in the stream, fewer bins matter less than tight packing now.
        score -= 20.0 * progress;
        // Many open bins => discourage yet another bin.
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if this placement leaves room exactly for the next
    // item, reward it strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 15.0;
    }

    // Mild alignment with mean residual: prefer bins near the mean (balanced
    // packing) to keep flexibility across the fleet.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

