    if next_item_size > 0 && pr > 0 && pr % next_item_size.max(1) == 0 {
        score -= 12.0;
    }

    // MUTATION: waste-ratio coupling — prefer hosts whose post-residual, as a
    // fraction of capacity, closely matches the mean residual of the pool;
