        // MUTATION: fresh-bin slack usability — a fresh bin's leftover after
        // this item (cap - item) is compared to next_item_size; if it can
        // still host the next item exactly, opening becomes much cheaper.
        if next_item_size > 0 {
            let fresh_left = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
