    if frac > 0.5 { score -= 11.0; }
    else if frac > 0.25 { score -= 4.0; }
    else if pr > 0 { score += 8.0; }

    // Tight-fit ladder.
    if pr > 0 && pr <= 5 { score -= 130.0; }
    else if pr > 5 && pr <= 9 { score -= 60.0; }

    // Waste risk for large unusable remainders.
    if pr > 0 {
        let waste_risk = 1.0 - tightness;
        score += 8.0 * waste_risk * (prf / cap);
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 650.0;
        } else if next_item_size < pr {
            let two_left = pr - next_item_size;
            if two_left <= 14 {
                score -= 300.0 - 20.0 * two_left as f64;
            } else {
                score -= 55.0 / (two_left as f64).sqrt();
            }
        } else {
            // next item cannot fit here: penalize near-miss slivers.
            let gap = (next_item_size - pr) as f64;
            score += 15.0 + 0.5 * gap;
            if gap <= 5 {
                score += (32.0 - 6.0 * gap) * (0.5 + 0.5 * (1.0 - progress));
            } else if gap <= 12 {
                score += 18.0 * (1.0 - gap / 12.0);
            }
            if gap >= 1.0 && gap <= 4.0 {
                score += 26.0 - 5.0 * gap;
            }
            // Chain-fill reward: residual is a multiple of next item size.
            if pr % next_item_size.max(1) == 0 {
                score -= 12.0;
            }
        }
    } else {
        score -= 40.0 * tightness;
    }

    // Exact fill of current bin residual by this item.
    if bin_residual == item_size {
        score -= 260.0;
    }

    // Last-chance bin: only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0 + 20.0 * tightness;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 90.0 + 0.55 * mean_residual + 60.0 * progress;
        if item_size >= 50 { new_bin_score -= 15.0; }
        if item_size * 20 >= bin_capacity * 17 { new_bin_score -= 12.0; }
