        if fitting_bins_count >= 3 { new_bin_score += 20.0; }
        if open_bins_count <= 2 { new_bin_score -= 14.0; }
        if progress < 0.15 { new_bin_score -= 18.0; }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_score -= 25.0;
            if next_item_size >= item_size / 2 { new_bin_score -= 8.0; }
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= 20 {
            let triple = item_size + next_item_size;
            if triple <= bin_capacity && bin_capacity - triple >= 10 {
                new_bin_score -= 10.0;
            }
        }
        // Opening a bin while the chosen fit would leave a small harmonic
        // remainder in an existing bin is wasteful.
        let cur_left = bin_residual as i64 - item_size as i64;
        if cur_left > 0 && cur_left <= 15 {
            new_bin_score += 24.0;
        }
        if progress < 0.35 && mean_residual < 30.0 {
            new_bin_score += 12.0;
        }
        if progress > 0.85 {
            new_bin_score += 30.0 * (progress - 0.85) / 0.15;
        }
        // Late-stream exact-chain opener.
        if progress > 0.7 && next_item_size > 0 && item_size + next_item_size == bin_capacity {
            new_bin_score -= 34.0;
        }
        // Waste-ratio coupling.
        if cur_left > 0 {
            let host_waste = cur_left as f64 / cap;
            let fresh_waste = (cap - item_size as f64) / cap;
            if host_waste > fresh_waste * 1.6 {
                new_bin_score -= 20.0 * (host_waste - fresh_waste).min(0.5) * 2.0;
            }
        }
        // Residual-hosting guard.
        if open_bins_count > 6 && mean_residual > 40.0 {
            new_bin_score += 18.0;
        }
        // Fresh bin hosting this item leaves room for the next item while
        // no open bin does — open cheaply.
        if next_item_size > 0 && cur_left > 0 && (cur_left as u32) < next_item_size && next_item_size <= bin_capacity - item_size {
            new_bin_score -= 16.0;
        }
        // Orphan lookahead: residual too small for next item by a wide margin.
        if next_item_size > 0 && cur_left > 0 && (cur_left as u32) < next_item_size / 2 && cur_left > 20 {
            new_bin_score -= 22.0;
        }
        // Homogeneity coupling: fresh bin vs pool mean residual.
        new_bin_score += 0.3 * (mean_residual - cap * 0.5);
