    }

    // Balance pressure: avoid dumping into already-tight bins when alternatives exist.
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual * 0.5 && fitting_bins_count > 1 {
        score += 10.0;
    }

    // Waste-density term.
    if next_item_size > 0 && pr > next_item_size {
        let unreachable = (pr - next_item_size) as f64 / cap;
        score += unreachable * unreachable * 55.0 * (0.35 + 0.65 * progress);
    }

