            && !(next_item_size > 0 && (fresh_left as u32) == next_item_size) {
            new_bin_cost += 30.0;
        }
        score += new_bin_cost;
    }

    // Consolidation pressure when many bins are open.
    if open_bins_count > 4 && prf < 0.3 * cap && pr > 0 {
        score -= 7.0;
    }

    // Spreading penalty, stronger late.
    score += open_bins_count as f64 * (0.4 + 0.65 * progress);

    // Mid-range residual reuse bonus.
    if pr > 20 && pr <= 45 {
        score -= 10.0 + 0.15 * (45.0 - prf);
    }

    // Penalize near-miss slivers just below next_item_size.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let miss = (next_item_size - pr) as f64;
        if miss > 5.0 && miss <= 12.0 {
            score += 18.0 * (1.0 - miss / 12.0);
        }
    }

    // Reward residuals in the 30-60 band aligned to multiples of 5.
    if pr >= 30 && pr <= 60 && pr % 5 == 0 {
        score -= 9.0;
    }

    // Penalize "almost reusable" slivers (1-4 units below next item).
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let miss = (next_item_size - pr) as f64;
        if miss >= 1.0 && miss <= 4.0 {
            score += 26.0 - 5.0 * miss;
        }
    }

    // Reward residuals matching next item's size class (chain fill).
    if next_item_size > 0 && pr > 0 && pr % next_item_size.max(1) == 0 {
        score -= 12.0;
    }

    // Waste-density term: penalize unreachable post-residual slack.
    if pr > next_item_size && next_item_size > 0 {
        let unreachable = (pr - next_item_size) as f64 / cap;
        score += unreachable * unreachable * 55.0 * (0.35 + 0.65 * progress);
    }

    // MUTATION: multi-copy chain lookahead — if the post-residual can host
    // exactly k copies of the next item, reward it proportionally (deeper
    // lookahead than the single-copy term above).
    if next_item_size > 0 && pr > 0 && pr >= next_item_size {
        let copies = pr / next_item_size;
        let used = copies * next_item_size;
        if used == pr {
            score -= 14.0 + 6.0 * copies.min(4) as f64;
        } else {
            let leftover = pr - used;
            if leftover < 10 {
                score -= 8.0;
            }
        }
    }

    // MUTATION: residual-to-capacity dead-space ratio floor — late in the
    // stream, any residual above half capacity that cannot host the next
    // item is a strong waste signal; penalize it quadratically.
    if progress > 0.55 && pr > cap * 0.5 && next_item_size > 0 && pr < next_item_size {
        score += 20.0 * (prf / cap) * (prf / cap);
    }

    score
}

