    // near-miss slivers waste capacity (dead-space refinement).
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let miss = (next_item_size - pr) as f64;
        if miss > 5.0 && miss <= 12.0 {
            score += 18.0 * (1.0 - miss / 12.0);
        }
    }

    // Reward bins whose remaining space after this item matches a common
    // size band (30-60), which future medium items can fill exactly.
    if pr >= 30 && pr <= 60 && pr % 5 == 0 {
        score -= 9.0;
    }

    // Dead-space ratio refinement — penalize post-residuals that
    // are just barely too small to host the next item (within 1-4 units),
    // since these "almost reusable" slivers accumulate as pure waste.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let miss = (next_item_size - pr) as f64;
        if miss >= 1.0 && miss <= 4.0 {
            score += 26.0 - 5.0 * miss;
        }
    }

    // Reward residuals exactly matching the next item's size class
    // even when the next item could arrive in multiple copies (chain fill).
    if next_item_size > 0 && pr > 0 && pr % next_item_size.max(1) == 0 {
        score -= 12.0;
    }

    // Waste-density term — penalize bins whose post-residual is a
    // large fraction of capacity yet unlikely to be filled by the next item,
    // scaling with how much of the stream remains (targets dead-space ratio).
    if pr > next_item_size && next_item_size > 0 {
        let unreachable = (pr - next_item_size) as f64 / cap;
        score += unreachable * unreachable * 55.0 * (0.35 + 0.65 * progress);
    }

    // MUTATION: fill-continuation bonus — reward bins whose post-residual,
    // divided by the next item's size, leaves a remainder small enough that
    // a future repeat of that item would nearly close the bin (chain density).
