        // pool already holds plenty of reusable space — make new bins costlier.
        if open_bins_count > 6 && mean_residual > 40.0 {
            new_bin_cost += 18.0;
        }
        // Projected waste-ratio guard — favor opening when the fresh bin
        // wastes proportionally less than the host would.
        if cur_left > 0 {
            let host_waste = cur_left as f64 / cap;
            let fresh_waste = (cap - item_size as f64) / cap;
