        if progress > 0.7 && next_item_size > 0 && item_size + next_item_size == bin_capacity {
            new_bin_cost -= 34.0;
        }
        // MUTATION: fresh-bin triple-exact chain — if item + next fills the
        // fresh bin exactly (zero dead space), opening is nearly free; and if
        // it leaves a small remainder <= 6, still strongly favored.
        if next_item_size > 0 {
            let fresh_left = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if fresh_left == 0 {
                new_bin_cost -= 48.0;
            } else if fresh_left > 0 && fresh_left <= 6 {
                new_bin_cost -= 26.0;
            }
        }
