    if pr >= 30 && pr <= 60 && pr % 5 == 0 {
        score -= 9.0;
    }

    // Penalize "almost reusable" slivers within 1-4 units below the next item.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let miss = (next_item_size - pr) as f64;
        if miss >= 1.0 && miss <= 4.0 {
            score += 26.0 - 5.0 * miss;
        }
    }

    // Reward residuals that are exact multiples of the next item's size.
    if next_item_size > 0 && pr > 0 && pr % next_item_size.max(1) == 0 {
        score -= 12.0;
    }

    // Waste-density term — penalize large post-residuals unreachable by next item.
    if pr > next_item_size && next_item_size > 0 {
        let unreachable = (pr - next_item_size) as f64 / cap;
        score += unreachable * unreachable * 55.0 * (0.35 + 0.65 * progress);
    }

    // MUTATION: dead-space compaction refinement — when a host fit would leave
    // a residual that is a large unreachable chunk, penalize proportionally to
    // remaining stream; complements the waste-density term for mid-range pr.
    if next_item_size > 0 && pr > next_item_size && pr <= 60 {
        let orphan = (pr - next_item_size) as f64;
        if orphan > 8.0 {
            score += 0.9 * (orphan - 8.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: multi-copy chain reward — if the next item fits exactly twice
    // into the post-residual (2x chain), strongly favor this bin.
    if next_item_size > 0 && pr > 0 && next_item_size * 2 == pr {
        score -= 20.0;
    }

    score
}

