        // next item exactly is nearly free (perfect chain fill).
        if progress > 0.3 && next_item_size > 0 && bin_capacity - item_size == next_item_size {
            new_bin_cost -= 28.0;
        }
        // NEW MUTATION: fresh-bin post-residual reusability discount — a
