    }

    // Reward residuals that are exact multiples of the next item's size.
    if next_item_size > 0 && pr > 0 && pr % next_item_size.max(1) == 0 {
        score -= 12.0;
    }

    // Waste-density term: penalize large unreachable post-residuals,
    // sharpened by next-item magnitude coupling.
    if pr > next_item_size && next_item_size > 0 {
        let unreachable = (pr - next_item_size) as f64 / cap;
        let scale = 55.0 + 0.25 * next_item_size as f64;
        score += unreachable * unreachable * scale * (0.35 + 0.65 * progress);
    }

    // NEW MUTATION: penalize residuals that no plausible future item can
    // fill exactly — the smallest common sizes are 1..=12, so a residual
    // just above a common small size is nearly dead space.
    if pr > 12 && pr < 30 {
        let mut fillable = false;
        for s in 1..=12u32 {
            if pr >= s && (pr % s == 0 || pr - s <= 3) {
                fillable = true;
                break;
            }
        }
        if !fillable {
            score += 10.0 * (1.0 - progress);
        }
    }

    score
}

