        // exactly is nearly free (perfect chain fill).
        if progress > 0.3 && next_item_size > 0 && bin_capacity - item_size == next_item_size {
            new_bin_cost -= 28.0;
        }
        // MUTATION: strengthen chain-fill logic. A fresh bin that leaves
        // room for the next item plus a small reusable tail is strongly
        // preferred over fragmenting a host bin.
        if next_item_size > 0 {
            let fresh_left = bin_capacity - item_size;
