pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item,
    // penalize leftovers that are just barely unusable for it.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            score -= 8.0 + 6.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: penalize more early in stream.
            score += (next - post_residual as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Penalize creating tiny unusable slivers (dead space below minimum item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when open bins are crowded or fits are poor.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // If mean residual across open bins is large, prefer reusing open bins.
        score += 30.0 + 40.0 * crowding;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        score -= 20.0 * progress;
        // If many bins fit, definitely avoid a new bin.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit bias).
    score += 0.05 * (bin_residual as f64 - post_residual as f64).signum() * (bin_residual as f64 / bin_capacity as f64);

    // Tie-break: prefer bins whose residual is close to the item (smooth best fit).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 5.0 * tightness;

    score
}

