            new_bin_cost -= 20.0;
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size {
            let orphan = next_item_size - pr;
            if orphan >= 15 {
                new_bin_cost -= 26.0;
            }
        }
        if fitting_bins_count >= 3 {
            new_bin_cost += 20.0;
        }
        if fitting_bins_count == 1 && pr > 0 && pr < 25 {
            new_bin_cost -= 18.0;
        }
        if progress > 0.5 && prf > cap / 3.0 && fitting_bins_count <= 2 {
            new_bin_cost -= 13.0;
        }
        if pr >= 1 && pr <= 8 && (1.0 - progress) > 0.3 {
            new_bin_cost -= 17.0;
        }
        if item_size * 20 >= bin_capacity * 17 {
            new_bin_cost -= 12.0;
        }
        if progress > 0.85 {
            new_bin_cost += 35.0 * (progress - 0.85) / 0.15;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && next_item_size >= item_size / 2 {
            new_bin_cost -= 8.0;
        }
        if next_item_size > 0 && next_item_size <= 20 {
            let triple = item_size + next_item_size;
            if triple <= bin_capacity && bin_capacity - triple >= 10 {
                new_bin_cost -= 10.0;
            }
        }
        if fitting_bins_count >= 1 && item_size * 3 < bin_residual {
            new_bin_cost -= 6.0;
        }
        let cur_left = bin_residual as i64 - item_size as i64;
        if cur_left > 0 && cur_left <= 15 {
            new_bin_cost += 24.0;
        }
        if progress < 0.35 && mean_residual < 30.0 {
            new_bin_cost += 14.0;
        }
        if next_item_size > 0 && cur_left > 0 && (cur_left as u32) < next_item_size / 2 && cur_left > 20 {
            new_bin_cost -= 22.0;
        }
        if open_bins_count > 6 && mean_residual > 40.0 {
            new_bin_cost += 18.0;
        }
        // Waste-ratio guard: open a fresh bin when the host would waste
        // proportionally more space than a fresh bin would.
        if cur_left > 0 {
            let host_waste = cur_left as f64 / cap;
            let fresh_waste = (cap - item_size as f64) / cap;
            if host_waste > fresh_waste * 1.6 {
                new_bin_cost -= 20.0 * (host_waste - fresh_waste).min(0.5) * 2.0;
            }
        }
        // Late-stream exact-chain opener.
        if progress > 0.7 && next_item_size > 0 && item_size + next_item_size == bin_capacity {
            new_bin_cost -= 34.0;
        }
        // When every open fit leaves a residual below the next item's size
        // (guaranteed dead slivers), opening a fresh bin is cheaper.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let any_good_fit = (bin_residual >= item_size + next_item_size) || (bin_residual == item_size);
            if !any_good_fit && item_size + next_item_size <= bin_capacity {
                new_bin_cost -= 16.0;
            }
        }
        // Mid-stream, a fresh bin whose post-residual equals the next item
        // exactly is nearly free (perfect chain fill).
        if progress > 0.3 && next_item_size > 0 && bin_capacity - item_size == next_item_size {
            new_bin_cost -= 28.0;
        }
        // MUTATION: three-item chain lookahead — reward a fresh bin sized so
        // that item + next leaves a residual matching a small third item class.
        if next_item_size > 0 {
            let r2 = bin_capacity - item_size - next_item_size;
            if item_size + next_item_size <= bin_capacity && r2 > 0 && r2 <= 25 {
                new_bin_cost -= 14.0 * (1.0 - progress);
            }
        }
        // MUTATION: early-stream, large items deserve dedicated bins rather
        // than fragmenting hosts that could serve small items later.
        if progress < 0.4 && item_size > bin_capacity / 2 && cur_left > 0 && cur_left < 20 {
            new_bin_cost -= 21.0;
        }
        // MUTATION: penalize opening bins whose fresh residual cannot plausibly
        // host the mean incoming item (dead-bin guard).
        let fresh_left = cap - item_size as f64;
        if next_item_size > 0 && (fresh_left as u32) < next_item_size && fresh_left < 0.25 * cap {
            new_bin_cost += 26.0;
        }
        score += new_bin_cost;
    }

    // Consolidation pressure when many bins are open.
    if open_bins_count > 4 && prf < 0.3 * cap && pr > 0 {
        score -= 7.0;
    }

    // Spreading penalty, stronger late.
    score += open_bins_count as f64 * (0.4 + 0.65 * progress);

    // Mid-range residual reuse bonus.
    if pr > 20 && pr <= 45 {
        score -= 10.0 + 0.15 * (45.0 - prf);
    }

    // Penalize near-miss slivers just below next_item_size.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let miss = (next_item_size - pr) as f64;
        if miss > 5.0 && miss <= 12.0 {
            score += 18.0 * (1.0 - miss / 12.0);
        }
        if miss >= 1.0 && miss <= 4.0 {
            score += 26.0 - 5.0 * miss;
        }
    }

    // Reward residuals in the 30-60 band on multiples of 5.
    if pr >= 30 && pr <= 60 && pr % 5 == 0 {
        score -= 9.0;
    }

    // Reward residuals that are exact multiples of the next item's size.
    if next_item_size > 0 && pr > 0 && pr % next_item_size.max(1) == 0 {
        score -= 12.0;
    }

    // Waste-density term: penalize large unreachable post-residuals.
    if pr > next_item_size && next_item_size > 0 {
        let unreachable = (pr - next_item_size) as f64 / cap;
        score += unreachable * unreachable * 55.0 * (0.35 + 0.65 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic waste penalty on post-residual, softened early in stream.
    let mut score = pr * (1.0 + norm_pr * (0.5 + progress));

    // Smooth polynomial coupling: residual tightness vs stream progress.
    // Late in the stream, compact residuals matter more (polynomial ramp).
    let tight = 1.0 - norm_pr;
    score -= tight * tight * progress * 20.0;

    // Reward large fill fraction non-linearly.
    score -= (norm_item * norm_item * (1.0 + progress)) * 15.0;

    // Lookahead: if next item fits into post-residual, reward strongly (smooth).
    if next_item_size > 0 {
        let fits_next = (norm_pr - norm_next).max(0.0);
        let fit_quality = if norm_next > 0.0 { fits_next / norm_next } else { 0.0 };
        score -= fit_quality * (pr - norm_next * cap).max(0.0) * 0.6;
        // Penalize post-residual that is just barely too small for next item (dead space).
        let gap = norm_next - norm_pr;
        if gap > 0.0 && gap < 0.25 {
            score += gap * gap * cap * 2.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening bins when many are open with room,
    // more so late in the stream; smooth in open_bins_count.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() + 1.0;
        score += crowding * (10.0 + 40.0 * progress);
        // But allow new bins early or when mean residual is very low.
        score -= (mean_residual / cap).max(0.0) * 25.0 * (1.0 - progress);
    }

    // Mild preference for bins tighter than average (smooth coupling).
    score += (pr - mean_residual) * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
