pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: perfectly tight (post_residual < 10 => dead space, great)
    // Class 1: small leftover usable by tiny items
    // Class 2: mid leftover
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit, huge reward
    } else if pr < 10 {
        score -= 30.0;
    } else if pr <= 20 {
        score -= 5.0;
    } else {
        // larger leftovers penalized mildly, scaled by divisibility
        let class = pr / 10; // harmonic bucket 2..10
        score += class as f64 * 2.0;
        // reward leftovers divisible by common item sizes (harmonic alignment)
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
    }

    // Lookahead: does the leftover fit the next item? Strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // extra reward if leftover is close to next item (tight pair)
        let gap = pr - next_item_size;
        if gap < 10 { score -= 8.0; }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize wasting good residual
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if item is huge relative to capacity, new bin is fine
        if item_size * 2 >= bin_capacity { score -= 25.0; }
        // fewer open bins -> opening new bin slightly cheaper
        score += open_bins_count as f64 * 1.5;
    }

    // Tightness ratio: prefer bins where item fills a large fraction
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 10.0;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

