    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A residual below the minimum item size (1) is impossible; treat residuals
    // in the "dead zone" (1..=12) as heavily penalized since few items fit.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0;
    } else if post_residual <= 25 {
        score += 15.0;
    } else if post_residual <= 45 {
        score += 5.0;
    } else {
        // Large leftover space is flexible; mild reward relative to baseline.
        score -= 8.0;
    }

    // Exact or near-exact fills are gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many open bins
    // when a compact set suffices; but relax late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (2.0 - progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when item is large relative
    // to typical residuals or current bins are mostly full.
    if bin_residual == bin_capacity {
        let mean_fill = mean_residual.max(0.0);
        if mean_residual < 15.0 && open_bins_count > 0 {
            // Existing bins are nearly full; opening fresh is reasonable.
            score -= 20.0;
        } else {
            // Prefer packing into existing bins; penalize new bin.
            score += 30.0 + mean_fill * 0.2;
        }
        // Lookahead: if next item is small, a fresh bin wastes capacity now.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 10.0;
        }
    }

    // Lookahead synergy: reward leaving a gap that the next item can use.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let gap_eff = next_item_size as f64 / post_residual as f64;
        if gap_eff > 0.6 {
            score -= 12.0 * gap_eff;
        }
    }

    // Prefer tighter fits generally: scale by relative fill quality.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

